<?php require_once __DIR__.'/config/database.php';$pageTitle='Gallery';include __DIR__.'/includes/header.php';$rows=$pdo->query('SELECT * FROM gallery ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><section class="section"><div class="container"><div class="section-heading center"><span>Photo Gallery</span><h2>আমাদের Gallery</h2></div><div class="public-gallery"><?php foreach($rows as $r):?><figure><img src="uploads/gallery/<?=htmlspecialchars($r['image'])?>" alt="<?=htmlspecialchars($r['title'])?>"><figcaption><?=htmlspecialchars($r['title'])?></figcaption></figure><?php endforeach;?></div><?php if(!$rows):?><p class="empty">বর্তমানে কোনো ছবি নেই।</p><?php endif;?></div></section><?php include __DIR__.'/includes/footer.php';?>